.section-regular-3 {
  -webkit-text-fill-color: inherit;
  background-color: #0000;
  background-clip: border-box;
  padding: 0 5% 80px;
  position: relative;
}

.slowing-sec {
  padding-bottom: 30px;
}

.container-large-3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

.heading-2 {
  color: var(--blue, #082753);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--h2, 40px);
