  border: 1px solid #009ce0;
  border-radius: 20px;
  flex-flow: column;
  justify-content: flex-start;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
}

.text-wrapper {
  /* wrapper for text content inside feature card */
}

