/* ==========================================================
   Card image  (Webflow: .full-width-image — plain, NO drop-shadow)
   Webflow: width: 100%; max-width: 3768px; height renders at natural ratio.
   No max-height, no object-fit override. Width constrained by card column.
   ========================================================== */
.fullWidthImage {
  display: block;
  width: 100%;
  height: auto;
  max-width: 100%;
}

/* ==========================================================
   @media (min-width: 1280px)
   Webflow line 21927: .feature-card.space-between → pl/pr 20px
   Webflow line 21944: .subheading-large → 25px/32px
   Webflow line 21932: .container-large-3 → max-width 1280px
   ========================================================== */
@media screen and (min-width: 1280px) {
  .featureCardBlue {
    padding-left: 20px;
    padding-right: 20px;
  }

  .containerLarge3 {
    max-width: 1280px;
  }

  .subheadingLargeWhite {
    font-size: 25px;
    line-height: 32px;
  }

  .fullWidthImage {
    width: 100%;
    max-width: 100%;
  }
}

/* ==========================================================
   @media (min-width: 1440px)
   Webflow line 23367: .feature-card.space-between → pl/pr 25px
   Webflow line 23376: .container-large-3 → max-width 1320px
   ========================================================== */
@media screen and (min-width: 1440px) {
  .featureCardBlue {
    padding-left: 25px;
    padding-right: 25px;
  }

  .containerLarge3 {
    max-width: 1320px;
  }

  .fullWidthImage {
    width: 100%;
    max-width: 100%;
  }
}

/* ==========================================================
   @media (max-width: 991px)
   Webflow line 24574: .section-regular-3.blue-sec.makeit-sec → margin-top: 0
   Webflow line 24662: .blue-sec → padding-left: 2%; padding-right: 2%
     (the .blue-sec rule at 991px applies because the section element
      also has the .blue-sec class — Webflow cascades these separately)
   Webflow line 24562: .feature-grid.margin-top-40px → 3-col stays
   ========================================================== */
@media screen and (max-width: 991px) {
  .sectionRegular3BlueSec {
    margin-top: 0;
    /* .blue-sec rule at 991px: padding-left/right override to 2% */
    padding-left: 2%;
    padding-right: 2%;
  }

  .heading2WhiteHeading {
    font-size: 35px;
    line-height: 45px;
  }

  .featureGrid {
    /* stays 3-col per Webflow line 24562 for margin-top-40px variant */
    grid-template-columns: 1fr 1fr 1fr;
  }
}

/* ==========================================================
   @media (max-width: 767px)
   Webflow line 27060: .section-regular-3 → padding-top: 0; padding-bottom: 0
   (overrides the base padding at mobile — the 479px rule restores for makeit-sec)
   feature-grid → 1 col
   ========================================================== */
@media screen and (max-width: 767px) {
  .sectionRegular3BlueSec {
    padding-top: 0;
    padding-bottom: 0;
    padding-left: 5%;
    padding-right: 5%;
    margin-top: 0;
  }

  .featureGrid {
    grid-template-columns: 1fr;
    margin-top: 20px;
  }

  .featureCardBlue {
    grid-column-gap: 0px;
    grid-row-gap: 0px;
    padding-left: 18px;
    padding-right: 18px;
  }

  .subheadingLargeWhite {
    text-align: center;
  }

  .paragraphSmall2WhiteOpacity {
    text-align: center;
  }

  .heading2WhiteHeading {
    font-size: 23px;
    line-height: 32px;
    margin-bottom: 10px;
    text-align: center;
  }

  .paragraphWhiteOpacity {
    text-align: center;
  }

  .fullWidthImage {
    width: 100%;
    max-width: 100%;
  }
}

/* ==========================================================
   @media (max-width: 479px)
   Webflow line 29623: .section-regular-3.blue-sec.makeit-sec →
     margin-top: 0; padding: 50px 5% 60px
   (restores padding that was zeroed at 767px for .section-regular-3 base)
   ========================================================== */
@media screen and (max-width: 479px) {
  .sectionRegular3BlueSec {
    margin-top: 0;
    padding: 50px 5% 60px;
  }

  .featureGrid {
    grid-template-columns: 1fr;
  }
}

